'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',grid:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5 M12 17v1',cart:'M2 3h3l3 13h11l3-10H6 M9 20h1 M18 20h1',wallet:'M3 6h18v15H3z M3 6V3h15v3 M16 12h5v4h-5z',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M1 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3 M16 5a4 4 0 0 1 0 7 M18 14a5 5 0 0 1 4 5v2',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v7l4 2',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',gear:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',check:'m5 12 4 4L20 5',globe:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M2 12h20 M12 2c-6 5-6 15 0 20 M12 2c6 5 6 15 0 20',download:'M12 2v13m-5-5 5 5 5-5 M3 16v6h18v-6',plus:'M12 4v16 M4 12h16',mail:'M2 5h20v15H2z m0 0 10 8L22 5',chart:'M3 3v18h18 M7 16v-5 M12 16V6 M17 16V9',refresh:'M20 8a8 8 0 1 0 1 8 M20 2v6h-6',pin:'M12 22s8-9 8-14A8 8 0 0 0 4 8c0 5 8 14 8 14 M12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6',edit:'m3 16 13-13 5 5-13 13H3z M13 6l5 5',support:'M3 13V10a9 9 0 0 1 18 0v3 M3 11h4v9H3z M17 11h4v9h-4z M17 20l-5 2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function icons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
let state={records:[],config:{},audit:[],member:{}},demo=false,tab='',side='',tableQuery='',tableStatus='',page=1,currentRows=[],currentType='',invoiceLines=[{name:'',qty:1,price:0}];
const names={overview:'Başlangıç',orders:'Siparişler',support:'Destek Talepleri',invoices:'Faturalar',customers:'Müşteriler',products:'Ürün & Hizmetler',general:'Genel Ayarlar',theme:'Tema Ayarları',security:'Güvenlik Ayarları',payments:'Ödeme Altyapıları',currencies:'Para Birimleri',staff:'Yönetici ve Personeller',permissions:'Yetkilendirme',templates:'Bildirim Şablonları',languages:'Dil Ayarları',analytics:'Raporlar',notes:'Notlar',reminders:'Hatırlatmalar',tasks:'Görevler',audit:'Etkinlik Kayıtları',invoiceNew:'Yeni Fatura Oluştur',customerDetail:'Müşteri Detayı'};
const menus=[['Ayarlar',[['general','Genel Ayarlar'],['security','Güvenlik ve KYC'],['staff','Yönetici ve Personeller'],['permissions','Yetkilendirme'],['moduller','Panel Modülleri'],['durum','Sistem Durumu']]],['Destek',[['gorusmeler','Ön Görüşme Talepleri'],['support','Destek Talepleri']]],['Araçlar',[['notes','Notlar'],['reminders','Hatırlatmalar'],['tasks','Görevler'],['audit','Etkinlik Kayıtları']]],['Site Yönetimi',[['sayfalar','Sayfalar'],['blog','Blog Yazıları'],['menu','Menü Düzenleyici'],['ikonlar','İkon Kütüphanesi']]],['Analytics',[['analytics','Raporlar']]],['Faturalandırma',[['invoices','Faturalar'],['payments','Ödeme Altyapıları']]],['Müşteriler',[['customers','Müşteri Listesi'],['yeni','Yeni Müşteri Ekle'],['partnerler','Partner Başvuruları'],['krediler','KYC Kredileri'],['degerlendirmeler','Ön Değerlendirmeler']]]];
$('#navigation').innerHTML=menus.map(([name,links])=>`<details><summary>${name}</summary><div class="dropdown">${links.map(([key,label])=>key==='customerNew'?`<button type="button" data-action="new" data-type="customer">${label}</button>`:`<a href="${key.startsWith('/')?key:'#'+key}"${key==='/kyc/'?' data-didit-link="true"':''}>${label}</a>`).join('')}</div></details>`).join('');
const route=()=>location.hash.slice(1).split('/')[0]||'overview';
const money=(v,c='USD')=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:['USD','BRL','EUR','TRY'].includes(c)?c:'USD',maximumFractionDigits:2}).format(Number(v)||0);
const date=v=>v?new Date(v).toLocaleDateString('tr-TR',{day:'2-digit',month:'short',year:'numeric'}):'—';
const initials=n=>String(n||'BM').split(' ').map(x=>x[0]).slice(0,2).join('');
const records=t=>(demo?sample:state.records).filter(x=>x.type===t);
const tag=s=>`<span class="tag ${/Ödenmedi|Pasif|Reddedildi|Kapandı/.test(s)?'red':/Bekliyor|İşlemde|Taslak/.test(s)?'amber':''}">${esc(s||'Aktif')}</span>`;
const btn=(s,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${s}</button>`;
const empty=(s='Henüz kayıt bulunmuyor.',detail='')=>`<div class="empty">${icon('file')}<span>${s}</span>${detail?`<small>${detail}</small>`:''}</div>`;
const panel=(title,content,i='file',tools='')=>`<section class="panel"><header class="panel-head"><span class="icon-tile">${icon(i)}</span><h2>${title}</h2><span class="tools">${tools}</span></header>${content}</section>`;
const stat=(label,value,detail='',cls='',i='chart',spark=false)=>`<article class="stat ${cls}"><div class="label">${label}${icon(i)}</div><strong>${value}</strong>${detail?`<small>${detail}</small>`:''}${spark?`<svg class="spark" viewBox="0 0 300 25" preserveAspectRatio="none"><path d="M0 21C25 22 30 10 50 13S80 25 100 19 125 9 150 15 175 24 200 17 235 22 260 11 285 7 300 4" fill="none" stroke="#5ca37c" stroke-width="1.5"/></svg>`:''}</article>`;
const sample=[...['Alex Morgan','Ryan Bergman','Evelyn Ellery','Joshua Janssen','Harper Bianchi','Christopher Fairbanks','Mia Ashworth','Thomas Moreau','Amalie Merrick','Andrew Ferreira'].map((name,i)=>({id:'demo-c'+i,type:'customer',name,email:name.toLowerCase().replaceAll(' ','.')+'@example.com',phone:'+90 555 000 00 '+String(i).padStart(2,'0'),country:['Türkiye','Fransa','Almanya','Birleşik Krallık'][i%4],currency:'USD',status:i===1?'Pasif':'Aktif',company:i===0?'Morgan Creative Studio':'',created:Date.now()-864e5*(i+10)})),...Array.from({length:10},(_,i)=>({id:'demo-i'+i,type:'invoice',name:'#'+(753-i*13),customer:'demo-c'+i,amount:[240,119,16.95,12,169.5,48,119,89.5,8.95,24][i],currency:'USD',due:'2026-11-01',status:i>6?'Ödendi':'Ödenmedi',created:Date.now()-i*864e5,lines:JSON.stringify([{name:'Oturum izni danışmanlık hizmeti',qty:1,price:240}])})),...['Oturum İzni','Şirket Kurulumu','Vize'].map((name,i)=>({id:'demo-o'+i,type:'order',name,customer:'demo-c'+i,status:'İşlemde',amount:900+200*i,currency:'USD',created:Date.now()})),...['Pasaport evrak kontrolü','Fatura bilgilerimin güncellenmesi','Oturum başvurumun durumu','Yeni hizmet başvurusu'].map((name,i)=>({id:'demo-t'+i,type:'ticket',name,customer:'demo-c'+i,status:'Yanıt Bekliyor',department:['Teknik Destek','Muhasebe','Genel'][i%3],created:Date.now()-i*864e5})),...['Yuki Tanaka','Marcus Bright','Priya Raghavan','Tobias Renner','Elena Marsh'].map((name,i)=>({id:'demo-s'+i,type:'staff',name,email:name.toLowerCase().replaceAll(' ','.')+'@example.com',group:['Destek Ekibi','Satış Ekibi','Muhasebe'][i%3],department:'Genel',status:'Aktif',created:Date.now()}))];
async function api(path,body,method){const r=await fetch('/api/admin/'+path,{method:method||(body?'POST':'GET'),headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'İşlem tamamlanamadı.');return d}
async function reload(){state=await api('bootstrap');$('#user-name').textContent=state.member.name;$('#user-avatar').textContent=initials(state.member.name)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();icons()}
function close(){ $('#modal').close() }
function heading(title=names[route()]){return `<div class="page-heading"><h1>${esc(title||'Yönetim Paneli')}</h1><button class="help-pill" data-action="help">${icon('help')} Yardım</button>${demo?'<span class="demo-label">ÖRNEK VERİ · Salt okunur önizleme</span>':''}<span class="breadcrumb">Başlangıç / ${esc(title)}</span></div>`}
function overview(){const invoices=records('invoice'),unpaid=invoices.filter(x=>x.status==='Ödenmedi'),paid=invoices.filter(x=>x.status==='Ödendi'),sum=a=>a.filter(x=>x.currency==='USD').reduce((n,x)=>n+Number(x.amount||0),0),cs=records('customer'),orders=records('order'),tickets=records('ticket');const overdue=unpaid.filter(x=>x.due&&new Date(x.due)<new Date());return `<div class="page-heading"><h1>Merhaba, ${esc((state.member.name||'Yönetici').split(' ')[0])}</h1><span class="subtext">İşte işletmenizin bugünkü görünümü.</span><span style="margin-left:auto">${btn(demo?'Gerçek kayıtlara dön':'Örnek verilerle önizle','demo','small soft')}</span></div>${demo?'<div class="info warning">Örnek verileri inceliyorsunuz. Bu sayılar gerçek satış, müşteri veya bakiye değildir. Düzenleme ve kaydetme kapalıdır.</div>':''}<div class="banner">${icon('shield')}<div><p>Yönetim çalışma alanınız hazır</p><small>Kayıtlar bu panele özeldir. Site ve diğer panellerin ayarları değişmez.</small></div><a class="btn soft" href="#general">Kuruluma devam et →</a></div><div class="stats">${stat('Bugünkü satış',money(sum(paid.filter(x=>new Date(x.created).toDateString()===new Date().toDateString()))),'USD · kaydedilen faturalar','','cart',demo)}${stat('Toplam tahsilat',money(sum(paid)),'USD · ödenen faturalar','','wallet',demo)}${stat('Yanıt bekliyor',tickets.filter(x=>x.status!=='Kapandı').length,'Destek talebi','','support',demo)}${stat('Müşteriler',cs.length,'Yönetim kayıtları','','users',demo)}${stat('Vadesi geçmiş faturalar',money(sum(overdue)),overdue.length+' fatura','danger','clock')}${stat('Vadesi yaklaşan',money(sum(unpaid.filter(x=>new Date(x.due)>=new Date()&&new Date(x.due)-new Date()<7*864e5))),'Önümüzdeki 7 gün · USD','amber','clock')}${stat('İşlemdeki siparişler',orders.filter(x=>x.status==='İşlemde').length,orders.length+' toplam sipariş','accent','gear')}${stat('Hatırlatmalar',records('reminder').filter(x=>x.due===new Date().toISOString().slice(0,10)).length,'Bugün gerçekleşecek','','bell')}</div><div class="columns"><div class="stack">${panel('Siparişler',`<div class="panel-body"><div class="chart-summary"><div><span class="tiny muted">BU AY TOPLAMI · USD</span><strong>${money(sum(orders))}</strong></div><div class="chart-legend"><span><i class="dot"></i>Siparişler</span><span><i class="dot lime"></i>Tahsilat</span></div></div>${chart(orders,paid)}</div>`,'cart',`<a class="btn small" href="#orders">Tümünü gör ↗</a>`)}${panel('Vadesi Yaklaşan Faturalar',unpaid.length?unpaid.slice(0,4).map(x=>`<div class="list-row"><div><button class="view-link" data-action="invoice-view" data-id="${x.id}">${esc(x.name)}</button><small>${esc(customerName(x.customer))} · ${date(x.due)}</small></div><strong class="right">${money(x.amount,x.currency)}</strong></div>`).join(''):empty('Vadesi yaklaşan fatura yok.'),'clock')}${panel('Çevrimiçi Personel',`<div class="online-summary">1 <small>Bu oturumda</small></div><div class="list-row"><span class="avatar">${esc(initials(state.member.name))}</span><div>${esc(state.member.name)}<small>${icon('pin')} Yönetim Paneli</small></div><span class="right tag">Yönetici</span></div><div class="panel-body" style="padding:10px 17px"><a class="tiny" href="#staff">Tüm personeli görüntüle →</a></div>`,'users')}${fold('Notlar','note','edit')}${fold('Hatırlatmalar','reminder','bell')}</div><div class="stack"><section class="map-card"><img src="/admin/world.svg" alt="Brezilya merkezli dünya haritası"><div class="map-label">BREZİLYA · 12 ÜLKE</div><div class="map-bubble"><small>MERKEZİMİZ</small><strong>São Paulo</strong><span>Brezilya’ya yeni bir başlangıç</span></div></section>${panel('Yanıt Bekleyen Talepler',tickets.length?tickets.slice(0,4).map(x=>`<div class="list-row"><div><button class="view-link" data-action="edit" data-id="${x.id}" data-type="ticket">${esc(x.name)}</button><small>${esc(customerName(x.customer))} · ${esc(x.department||'Genel')}</small></div><span class="right">${tag(x.status)}</span></div>`).join(''):empty('Yanıt bekleyen destek talebi yok.'),'support',`<a href="#support" class="tiny">Tümünü gör →</a>`)}${panel('Çevrimiçi Müşteriler',empty('Canlı oturum takibi bağlı değil.','Müşteri kayıtlarını Müşteriler bölümünde görüntüleyebilirsiniz.'),'users')}${fold('Görevler','task','check')}</div></div>`}
function chart(orders=[],paid=[]){const buckets=a=>Array.from({length:6},(_,i)=>a.filter(x=>x.currency==='USD'&&new Date(x.created).getMonth()===new Date(new Date().getFullYear(),new Date().getMonth()-5+i,1).getMonth()&&new Date(x.created).getFullYear()===new Date(new Date().getFullYear(),new Date().getMonth()-5+i,1).getFullYear()).reduce((n,x)=>n+Number(x.amount||0),0));const a=buckets(orders),b=buckets(paid),max=Math.max(100,...a,...b),p=v=>v.map((n,i)=>`${50+i*83},${165-n/max*130}`).join(' ');return `<div class="chart"><svg viewBox="0 0 500 200" role="img" aria-label="Son altı ayın USD sipariş ve tahsilat grafiği">${[0,1,2,3].map(i=>`<line x1="50" x2="465" y1="${35+i*43}" y2="${35+i*43}" stroke="#e8eee3"/><text x="0" y="${39+i*43}">${Math.round(max*(3-i)/3)}</text>`).join('')}<polyline points="${p(a)}" fill="none" stroke="#00695c" stroke-width="2"/><polyline points="${p(b)}" fill="none" stroke="#a8ce71" stroke-width="2"/>${a.map((_,i)=>`<text x="${50+i*83}" y="192" text-anchor="middle">${new Date(new Date().getFullYear(),new Date().getMonth()-5+i,1).toLocaleDateString('tr-TR',{month:'short'})}</text>`).join('')}</svg></div>`}
function fold(title,type,i){const list=records(type);return `<details class="panel collapsed"><summary class="panel-head"><span class="icon-tile">${icon(i)}</span>${title}<span class="muted tiny">${list.length?list.length:''}</span></summary>${list.length?list.slice(0,3).map(x=>`<div class="list-row">${esc(x.name)}<small class="right">${esc(x.status||'')}</small></div>`).join(''):empty('Henüz '+title.toLowerCase()+' yok.')}<div class="panel-body">${btn('+ Ekle','new','small',`data-type="${type}"`)}</div></details>`}
const customerName=id=>records('customer').find(x=>x.id===id)?.name||'—';
const tabs=(labels)=>`<div class="tabs">${labels.map(t=>`<button class="${tab===t?'active':''}" data-tab="${esc(t)}">${esc(t)}</button>`).join('')}</div>`;
function input(name,label,value='',type='text',required=false){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function select(name,label,opts,value=''){return `<label class="field">${label}<select name="${name}">${opts.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
const area=(name,label,value='')=>`<label class="field">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const check=(name,label,value=false)=>`<label class="switch"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const row=(label,control,hint='')=>`<div class="form-row"><label>${label}</label><div>${control}${hint?`<p class="hint">${hint}</p>`:''}</div></div>`;
const field=(name,value='',type='text')=>`<input name="${name}" type="${type}" value="${esc(value)}">`;
const opts=(name,options,value)=>`<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
const langs=['TR','EN','PT-BR','AZ','MK','RU','ES','FA','AR','TK','UZ','KY','ID'];
const languageTabs=()=>`<div class="language-tabs">${langs.map((x,i)=>`<button type="button" class="${i===0?'active':''}" data-language="${x}">${x}</button>`).join('')}</div>`;
function configForm(section,content){return `<form data-config="${section}"><div class="info">Bu bölümdeki değişiklikler yönetim taslağı olarak saklanır. Canlı web sitesine, giriş güvenliğine veya diğer panellere otomatik uygulanmaz.</div>${content}<div class="form-actions">${btn('Değişiklikleri Kaydet','submit','primary','type="submit"')}</div></form>`}
function general(){const labels=['Temel','SEO','Yerelleştirme','Üyelik','Permalinks','API','Sosyal Giriş','Gelişmiş'];if(!labels.includes(tab))tab=labels[0];const section='general-'+labels.indexOf(tab),v=state.config[section]||{};let content='';if(tab==='Temel')content=row('Firma Unvanı',languageTabs()+field('title',v.title||'Brazil Migration'),'Firmanızın resmî unvanını tanımlayın.')+row('Firma Bilgileri',area('company','',v.company||''),'Vergi numarası, vergi dairesi ve ticaret sicili bilgileri.')+row('Firma Adresi',area('address','',v.address||'São Paulo, Brezilya'))+row('E-posta Adresleri',field('email',v.email||'','email'))+row('Telefon Numaraları',field('phone',v.phone||'','tel'));else if(tab==='SEO')content=languageTabs()+`<div class="seo-layout"><div>${input('title','SEO Başlığı',v.title||'Brazil Migration | Brezilya’da Yeni Bir Başlangıç')}${area('description','SEO Açıklaması',v.description||'Brezilya’da oturum, şirket kurulumu ve yaşam planınız için São Paulo odaklı danışmanlık.')}${input('format','Alt Sayfa Başlık Yerleşimi',v.format||'{page_title} · {home_title}')}${input('keywords','SEO Anahtar Kelimeleri',v.keywords||'Brezilya, oturum izni, São Paulo')}</div><div class="stack"><article class="preview-card"><header>${icon('search')} Arama Sonucu Önizlemesi</header><div><small>brazilmigration</small><h3 id="seo-preview-title">${esc(v.title||'Brazil Migration')}</h3><p id="seo-preview-description">${esc(v.description||'Brezilya’da yeni bir başlangıç.')}</p></div></article><article class="preview-card"><header>Paylaşılan Bağlantı</header><img src="/brazil-migration-logo.png" alt="Brazil Migration"></article></div></div>`;else if(tab==='Yerelleştirme')content=row('Site Açılış Dili',opts('opening',['Otomatik Algıla','Türkçe','Português (Brasil)'],v.opening))+row('Yerel Dil',opts('language',['Türkçe','English','Português (Brasil)'],v.language))+row('Yerel Para Birimi',opts('currency',['US Dollar (USD)','Real (BRL)','Euro (EUR)','Türk Lirası (TRY)'],v.currency))+row('Varsayılan Ülke',opts('country',['Brezilya','Türkiye'],v.country))+row('Tarih Formatı',opts('date',['23 Eki 2026','23/10/2026','2026-10-23'],v.date))+row('Saat Dilimi',opts('timezone',['America/Sao_Paulo','Europe/Istanbul','UTC'],v.timezone));else if(tab==='Üyelik')content=row('Yeni Kayıtlar',check('registration','Müşteri kaydını etkinleştir',v.registration??true))+row('E-posta Doğrulama',check('verify','E-posta doğrulaması iste',v.verify??true))+row('Kullanım Koşulları',field('terms',v.terms||''),'Kullanım koşulları sayfası adresi.');else if(tab==='Permalinks')content=row('Sayfa Bağlantıları',field('pages',v.pages||'/{sayfa}/'))+row('Hizmet Bağlantıları',field('services',v.services||'/{hizmet}/'));else if(tab==='API')content=`<div class="info warning">Harici API bağlantısı tanımlanmamış. Bu form yalnızca bağlantı notlarını saklar; buraya gizli anahtar veya parola yazmayın.</div>`+row('Bağlantı Adı',field('name',v.name||''))+row('Notlar',area('notes','',v.notes||''));else if(tab==='Sosyal Giriş')content=`<div class="cards-3">${['Google','Microsoft','Apple'].map(x=>`<div class="security-card"><h3>${x}</h3><p>Sağlayıcı bağlantısı kurulmadı.</p>${tag('Bağlı değil')}</div>`).join('')}</div>`+row('Planlama Notu',area('notes','',v.notes||''));else content=row('Bakım Modu',check('maintenance','Bakım modu taslağı',v.maintenance))+row('Yönetici Notları',area('notes','',v.notes||''));return heading()+`<section class="panel">${tabs(labels)}<div class="settings">${configForm(section,content)}</div></section>`}
function theme(){const labels=['Logo/Markalama','Tema Yönetimi','Anasayfa','Arka Planlar','Gelişmiş'];if(!labels.includes(tab))tab=labels[0];const section='theme-'+labels.indexOf(tab),v=state.config[section]||{};let content='';if(tab==='Logo/Markalama'){if(!side)side='Web Sitesi';content=`<div class="settings-split"><aside class="side-tabs">${['Web Sitesi','Müşteri Paneli','Fatura','Yönetim Paneli'].map(x=>`<button type="button" class="${side===x?'active':''}" data-side="${x}">${x}<small>Logo ve marka görünümü</small></button>`).join('')}</aside><div><div class="section-title">${esc(side)}</div><div class="logo-grid">${['Gündüz','Gece','Favicon'].map((x,i)=>`<div class="logo-tile ${i===1?'dark':''}"><div class="tile-top">${x}</div><img src="/brazil-migration-logo.png" alt="${x} logosu"><small>Mevcut Brazil Migration logosu</small></div>`).join('')}</div><h3 class="section-title">Site Renkleri</h3><p class="tiny muted">Mevcut marka renkleri korunur.</p><div class="color-fields"><label>Birincil <input type="color" name="primary" value="${esc(v.primary||'#1b5e20')}"></label><label>İkincil <input type="color" name="secondary" value="${esc(v.secondary||'#00695c')}"></label><label>Vurgu <input type="color" name="accent" value="${esc(v.accent||'#a8ce71')}"></label></div>${row('Logo Notları',field('logo-notes',v['logo-notes']||''))}</div></div>`}else if(tab==='Anasayfa')content=languageTabs()+`<table><thead><tr><th>Öğe</th><th>Etkinleştir</th><th>Sıralama</th></tr></thead><tbody>${['Ana Slider','Hizmetler','Brezilya ve 12 Ülke Haritası','Hakkımızda','Neden Biz','Yaşam Planı','Ön Değerlendirme','İletişim'].map((x,i)=>`<tr><td>${x}</td><td>${check('enabled-'+i,'',v['enabled-'+i]??true)}</td><td><input aria-label="${x} sıralaması" style="width:70px" type="number" min="1" name="order-${i}" value="${esc(v['order-'+i]||i+1)}"></td></tr>`).join('')}</tbody></table>`;else if(tab==='Arka Planlar')content=`<div class="background-grid">${[['Oturum İzni','oturum'],['Vatandaşlık','vatandaslik'],['Şirket Kurulumu','sirket'],['İletişim','iletisim'],['Değerlendirme','degerlendirme'],['Kaynaklar','kaynaklar'],['İçerik Planı','icerik'],['Giriş','giris']].map(([n,f])=>`<div class="background-tile"><img src="/images/marketing-v2/${f}-768.webp" alt="${n}" loading="lazy"><div>${n}${btn(icon('search'),'image','small',`type="button" data-src="/images/marketing-v2/${f}.webp" data-title="${n}"`)}</div></div>`).join('')}</div>`+row('Görsel Notları',area('notes','',v.notes||''));else if(tab==='Tema Yönetimi')content=`<div class="preview-card"><header>Brazil Migration · Mevcut Tema</header><div><img src="/brazil-migration-logo.png" alt="Brazil Migration" style="max-width:300px"><p>Poppins yazı tipi · Yeşil ve krem renkler · Masaüstü ve mobil uyumlu düzen</p>${tag('Aktif tema')}</div></div>`;else content=row('Sayfa Detay Kenar Çubuğu',check('sidebar','Etkinleştir',v.sidebar??true))+row('Haber Detay Kenar Çubuğu',check('news','Etkinleştir',v.news??true))+row('Yönetim Paneli Yazı Tipi',opts('font',['Poppins'],v.font))+row('Hizmet Satın Al Bağlantısı',field('link',v.link||'/iletisim/'));return heading()+`<section class="panel">${tabs(labels)}<div class="settings">${configForm(section,content)}</div></section>`}
function security(){const labels=['Ayarlar','Kimlik Doğrulama','BotShield','Captcha Güvenlik','İşlem Kısıtlama','Spam Koruması','Yasak Listesi','Yedekleme'];if(!labels.includes(tab))tab=labels[0];const section='security-'+labels.indexOf(tab),v=state.config[section]||{};let content='';if(tab==='Ayarlar')content=row('Yönetim Paneli Erişim Yolu',field('path',v.path||'/admin/'),'Yalnızca planlama alanıdır; mevcut adresi değiştirmez.')+row('Yönetim Paneli IP Kısıtlaması',field('ips',v.ips||''),'Planlanan IP adreslerini virgülle ayırın.')+row('Güvenilen Proxy’ler',area('proxies','',v.proxies||''))+row('Iframe Clickjacking Koruması',check('frame','Etkinleştir',v.frame??true))+row('Parola Uzunluğu',field('length',v.length||12,'number'))+row('Parola Sıfırlama Döngüsü',opts('cycle',['6 ay','12 ay','Zorunlu değil'],v.cycle));else if(tab==='Kimlik Doğrulama'){const sides=['İki Adımlı Doğrulama','Konum Doğrulama','IP Doğrulama','Passkey','JetPass','Ülke Kuralları'];if(!sides.includes(side))side=sides[0];content=`<div class="settings-split"><aside class="side-tabs">${sides.map(x=>`<button type="button" data-side="${x}" class="${side===x?'active':''}">${x}<small>Kimlik doğrulama seçenekleri</small></button>`).join('')}</aside><div><div class="info warning">Panel erişimi mevcut site kimliğine bağlıdır. Buradaki seçenekler bir güvenlik politikası taslağıdır; etkin bir doğrulama sağlayıcısı oluşturmaz.</div>${side==='İki Adımlı Doğrulama'?`<div class="cards-3">${['TOTP','E-posta','SMS'].map((x,i)=>`<div class="security-card"><h3>${x}</h3><p>${['Kimlik doğrulama uygulaması','E-posta ile doğrulama kodu','Telefon ile doğrulama kodu'][i]}</p>${check('method-'+i,'Taslağa ekle',v['method-'+i])}</div>`).join('')}</div>`:''}${row('Müşteriler için',check('customer-'+side,'Politika taslağına ekle',v['customer-'+side]))}${row('Personel için',check('staff-'+side,'Politika taslağına ekle',v['staff-'+side]))}${row('Güvenilir Cihaz Süresi',field('days-'+side,v['days-'+side]||30,'number'),'Gün cinsinden.')}${row('Notlar',area('notes-'+side,'',v['notes-'+side]||''))}</div></div>`}else if(tab==='Yedekleme')content=`<div class="info">Bu yönetim panelindeki kayıtları JSON olarak indirebilirsiniz. Bu indirme tüm sitenin veritabanı veya dosya yedeği değildir.</div>${btn(icon('download')+' Yönetim Kayıtlarını İndir','backup','','type="button"')}`;else content=row('Durum',check('enabled','Politika taslağına ekle',v.enabled))+row(tab+' Kuralları',area('rules','',v.rules||''),'Kuralları satır satır yazın. Uygulamaya alınmadan önce sunucu yapılandırması gerekir.');return heading()+`<section class="panel">${tabs(labels)}<div class="settings">${configForm(section,content)}</div></section>`}
function payments(){if(!['Başlangıç','Tüm Modüller'].includes(tab))tab='Başlangıç';const v=state.config.payments||{};return heading()+`<section class="panel">${tabs(['Başlangıç','Tüm Modüller'])}<div class="settings">${configForm('payments',`<div class="info warning">Ödeme sağlayıcısı bağlı değil. Bu ekran ödeme altyapısı seçiminizi kaydeder; ödeme tahsil etmez. Gizli anahtarları bu forma girmeyin.</div>${row('Etkin Modül Seçimi',opts('provider',['Banka Havalesi / EFT','iyzico','PayTR','Shopier','Garanti BBVA Sanal POS'],v.provider))}${row('Banka Bilgileri',area('bank','',v.bank||''),'Alıcı adı ve IBAN bilgileri.')}${row('Ödeme Açıklaması',field('description',v.description||''))}<h3 class="section-title">Ödeme Modülleri</h3><div class="module-grid">${[['iyzico','Kart ile ödeme altyapısı'],['PayTR','Sanal POS ödeme altyapısı'],['Shopier','Online ödeme çözümü'],['Garanti BBVA','Banka sanal POS altyapısı']].map(([name,desc])=>`<article class="module"><h3>${name}</h3><p>${desc}. Entegrasyon henüz kurulmadı.</p>${btn('Yapılandırma Notu','provider','small',`type="button" data-name="${name}"`)}</article>`).join('')}</div>`)}</div></section>`}
const languageNames=[['Türkçe','tr'],['English','en'],['Português (Brasil)','pt-br'],['Azərbaycan','az'],['Македонски','mk'],['Русский','ru'],['Español','es'],['فارسی','fa'],['العربية','ar'],['Türkmençe','tk'],['Oʻzbekcha','uz'],['Кыргызча','ky'],['Bahasa Indonesia','id']];
function languages(){const v=state.config.languages||{};return heading()+`<div class="info">Dil seçenekleri listelenir. Çeviri yapılmaz; varsayılan dil ve görünürlük tercihleri taslak olarak kaydedilir.</div><section class="panel"><form data-config="languages"><div class="toolbar"><input class="table-search" data-filter-static placeholder="Dil ara…" aria-label="Dil ara">${btn('Değişiklikleri Kaydet','submit','primary','type="submit"')}</div><div class="table-scroll"><table><thead><tr><th>Dil Adı</th><th>Çeviri</th><th>Varsayılan</th><th>Durum</th></tr></thead><tbody>${languageNames.map(([n,c])=>`<tr><td>${n} <small>${c}</small></td><td><span class="tag gray">Çeviri uygulanmadı</span></td><td><input type="radio" name="default" value="${c}" ${c===(v.default||'tr')?'checked':''} aria-label="${n} varsayılan dil"></td><td>${check(c,n+' görünür',v[c]??true)}</td></tr>`).join('')}</tbody></table></div></form></section>`}
function currencies(){const v=state.config.currencies||{};return heading()+`<div class="info">Para birimi görünürlüğü yönetim taslağıdır. Canlı döviz kuru servisi bağlı değildir; kur dönüşümü yapılmaz.</div><section class="panel"><form data-config="currencies"><div class="toolbar"><input data-filter-static class="table-search" placeholder="Para birimi ara…" aria-label="Para birimi ara">${btn('Değişiklikleri Kaydet','submit','primary','type="submit"')}</div><div class="table-scroll"><table><thead><tr><th>Ülke / Bölge</th><th>Birim Adı</th><th>Birim Kodu</th><th>Simge</th><th>Kur</th><th>Yerel Para Birimi</th><th>Durum</th></tr></thead><tbody>${[['Brezilya','Brezilya Reali','BRL','R$'],['Amerika Birleşik Devletleri','US Dollar','USD','$'],['Türkiye','Türk Lirası','TRY','₺'],['Avrupa Birliği','Euro','EUR','€'],['Birleşik Krallık','British Pound','GBP','£'],['Azerbaycan','Manat','AZN','₼'],['Kuzey Makedonya','Denar','MKD','ден']].map(([country,n,c,s])=>`<tr><td>${country}</td><td>${n}</td><td>${c}</td><td>${s}</td><td><span class="muted">Bağlı değil</span></td><td><input type="radio" name="default" value="${c}" ${c===(v.default||'USD')?'checked':''} aria-label="${c} yerel para birimi"></td><td>${check(c,'',v[c]??['BRL','USD','TRY','EUR'].includes(c))}</td></tr>`).join('')}</tbody></table></div></form></section>`}
const templateDefaults=['Yeni Yazı','Yeni Duyuru','Evrak Doğrulama (Reddedildi)','Evrak Doğrulama (Onaylandı)','Kişisel Veri Talebi (Reddedildi)','Kişisel Veri Talebi (Onaylandı)','Adres Bilgileri Güncellendi','Telefon Numarası Değiştirildi','Ad Soyad Değiştirildi','Müşteriye Özel Mesaj','İletişim Formu Yanıtı','Fatura Oluşturuldu','Fatura Hatırlatması','Ödeme Alındı','Yeni Sipariş','Hizmet Yenileme','Destek Talebi Oluşturuldu'];
function templates(){return heading()+`<section class="panel"><div class="settings"><div class="info">E-posta ve SMS şablonları burada hazırlanır. Gönderim sağlayıcısı bağlı olmadığından bu ekran mesaj göndermez.</div><div class="settings-split"><aside class="side-tabs">${['Tüm Şablonlar','Bülten','Genel Bildirimler','Yönetici Bildirimleri','Fatura','Sipariş','Ürün/Hizmet','Destek','Güvenlik'].map(x=>`<button data-side="${x}" class="${(side||'Tüm Şablonlar')===x?'active':''}">${x}</button>`).join('')}</aside><div>${renderTable('template')}</div></div></div></section>`}
function permissions(){const v=state.config.permissions||{};const groups={'Hesap Ayarları':['Görüntüleme','Düzenleme'],'Faturalandırma':['Faturalar','Ödemeler','Para Birimleri','İndirimler'],'Personel ve Yöneticiler':['Listeleme','Görüntüleme','Oluşturma','Düzenleme','Yetkilendirme'],'Panel':['Gelir İstatistiği','Müşteri İstatistiği','Siparişler Grafiği','Notlar','Hatırlatmalar','Görevler'],'Ayarlar':['Genel Bilgiler','Tema Ayarları','Yerelleştirme','SEO Ayarları'],'Güvenlik':['Güvenlik Ayarları','Yedekleme'],'Siparişler':['Görüntüleme','Oluşturma','Düzenleme'],'Müşteriler':['Görüntüleme','Oluşturma','Düzenleme'],'Bildirim Şablonları':['Görüntüleme','Düzenleme']};return heading()+`<section class="panel"><div class="settings">${configForm('permissions',row('Grup Adı',field('name',v.name||'Yönetici Grubu'))+`<div class="info warning">Yetki matrisi taslak olarak saklanır. Bu ayrı yönetim alanına şu anda yalnızca site sahibi erişebilir; personel erişimini veya diğer panellerin yetkilerini değiştirmez.</div><label class="info" style="display:block"><input type="checkbox" data-all-permissions> Tüm Yetkileri Seç</label><div class="permission-grid">${Object.entries(groups).map(([g,ps],i)=>`<section class="permission-group"><h3>${g}</h3>${ps.map((p,j)=>`<label><input type="checkbox" data-permission name="p${i}-${j}" ${v['p'+i+'-'+j]?'checked':''}>${p}</label>`).join('')}</section>`).join('')}</div>`)}</div></section>`}
const typeTitles={customer:'Müşteri',invoice:'Fatura',order:'Sipariş',ticket:'Destek Talebi',staff:'Personel',template:'Şablon',note:'Not',reminder:'Hatırlatma',task:'Görev',product:'Ürün / Hizmet'};
function tableData(type){let rows=records(type);if(type==='template'){rows=[...rows,...templateDefaults.filter(n=>!rows.some(x=>x.name===n)).map((name,i)=>({id:'template-'+i,type,name,category:/Fatura|Ödeme/.test(name)?'Fatura':/Sipariş/.test(name)?'Sipariş':/Destek/.test(name)?'Destek':/Yazı|Duyuru/.test(name)?'Bülten':'Genel Bildirimler',status:'Taslak',channel:'E-posta',body:''}))];if(side&&side!=='Tüm Şablonlar')rows=rows.filter(x=>x.category===side)}return rows.filter(x=>(!tableQuery||Object.values(x).join(' ').toLocaleLowerCase('tr').includes(tableQuery.toLocaleLowerCase('tr')))&&(!tableStatus||x.status===tableStatus))}
function renderTable(type){currentType=type;currentRows=tableData(type);const pages=Math.max(1,Math.ceil(currentRows.length/10));page=Math.min(page,pages);const list=currentRows.slice((page-1)*10,page*10);let headings={customer:['Ad Soyad','E-posta / Telefon','Ülke / Para Birimi','Kayıt Tarihi','Durum',''],invoice:['Müşteri','Fatura No','Tutar','Son Ödeme','Belge Türü','Durum',''],staff:['İsim','E-posta','Yetki Grubu','Departman','Durum',''],template:['Şablon','Kategori','Gönderim','Durum',''],order:['Sipariş / Hizmet','Müşteri','Tutar','Tarih','Durum',''],ticket:['Konu','Müşteri','Departman','Tarih','Durum',''],product:['Ürün / Hizmet','Açıklama','Fiyat','Durum','']}[type]||['Başlık','Açıklama','Tarih','Durum',''];return `<div class="table-shell"><div class="toolbar"><input class="table-search" id="table-search" placeholder="Ara…" aria-label="Kayıtlarda ara" value="${esc(tableQuery)}"><select id="table-status" aria-label="Durum filtresi"><option value="">Tüm durumlar</option>${[...new Set(records(type).map(x=>x.status).filter(Boolean))].map(x=>`<option ${x===tableStatus?'selected':''}>${esc(x)}</option>`).join('')}</select>${btn(icon('download'),'export','small','aria-label="CSV indir"')}${type==='staff'?'<a href="#permissions" class="btn small">Yetkilendirme</a>':''}${btn('+ Yeni '+(typeTitles[type]||'Kayıt'),'new','primary',`data-type="${type}"`)}</div><div class="table-scroll"><table><thead><tr>${headings.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${list.length?list.map(x=>tableRow(x)).join(''):`<tr><td colspan="${headings.length}">${empty('Kayıt bulunamadı.',tableQuery?'Aramanızı veya filtrelerinizi değiştirebilirsiniz.':'Yeni bir kayıt ekleyerek başlayabilirsiniz.')}</td></tr>`}</tbody></table></div><div class="table-bottom"><span>${currentRows.length} kayıt · ${currentRows.length?(page-1)*10+1:0}–${Math.min(page*10,currentRows.length)} arası gösteriliyor</span><div class="pagination">${btn('‹','prev','small',page===1?'disabled':'')}<button class="selected">${page}</button><span style="padding:5px">/ ${pages}</span>${btn('›','next','small',page===pages?'disabled':'')}</div></div></div>`}
function tableRow(x){let cells=[],action=btn('Düzenle','edit','small',`data-id="${x.id}" data-type="${x.type}"`);if(x.type==='customer'){cells=[`<a href="#customerDetail/${x.id}">${esc(x.name)}</a><small>${esc(x.company)}</small>`,`${esc(x.email)}<small>${esc(x.phone)}</small>`,`${esc(x.country||'—')}<small>${esc(x.currency||'USD')}</small>`,date(x.created),tag(x.status),action]}else if(x.type==='invoice')cells=[esc(customerName(x.customer)),esc(x.name),money(x.amount,x.currency),date(x.due),'<span class="tag gray">İç kayıt</span>',tag(x.status),btn('Görüntüle','invoice-view','small',`data-id="${x.id}"`)];else if(x.type==='staff')cells=[esc(x.name),esc(x.email),esc(x.group||'—'),esc(x.department||'Genel'),tag(x.status),action];else if(x.type==='template')cells=[esc(x.name),esc(x.category||'Genel Bildirimler'),esc(x.channel||'E-posta'),tag(x.status),action];else if(x.type==='order')cells=[esc(x.name),esc(customerName(x.customer)),money(x.amount,x.currency),date(x.created),tag(x.status),action];else if(x.type==='ticket')cells=[esc(x.name),esc(customerName(x.customer)),esc(x.department||'Genel'),date(x.created),tag(x.status),action];else if(x.type==='product')cells=[esc(x.name),esc(x.description||'—'),money(x.amount,x.currency),tag(x.status),action];else cells=[esc(x.name),esc((x.description||'').slice(0,80)),date(x.due||x.created),tag(x.status||'Açık'),action];return `<tr>${cells.map(x=>`<td>${x}</td>`).join('')}</tr>`}
function listPage(type){let summary='';if(type==='customer')summary=`<div class="stats">${stat('Aktif hesap',records(type).filter(x=>x.status==='Aktif').length,'','accent','users')}${stat('Pasif hesap',records(type).filter(x=>x.status==='Pasif').length,'','amber','users')}${stat('Yeni müşteri',records(type).filter(x=>Date.now()-x.created<30*864e5).length,'Son 30 gün','','users')}${stat('Toplam müşteri',records(type).length,'','','users')}</div>`;if(type==='invoice')summary=`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${['Ödenmedi','Ödendi','İptal Edildi'].map((s,i)=>stat(s,money(records(type).filter(x=>x.status===s&&x.currency==='USD').reduce((n,x)=>n+x.amount,0)),'USD · kayıtlı faturalar',i===0?'amber':i===1?'accent':'danger','wallet')).join('')}</div>`;return heading()+summary+(type==='staff'?'<div class="info">Personel kayıtları bu yönetim alanına özeldir. Kayıt oluşturmak erişim daveti göndermez; rol ve departman bilgileri burada yönetilir.</div>':'')+`<section class="panel">${renderTable(type)}</section>`}
function customerDetail(){const c=records('customer').find(x=>x.id===location.hash.split('/')[1]);if(!c)return heading()+empty('Müşteri bulunamadı.');const labels=['Özet','Profil','Kişiler','Alt Hesaplar','Faturalar','Cari Ekstre','Ürün & Hizmetler','Destek Talepleri','Satış Ortaklığı','Mesajlar','Etkinlik Kayıtları','Notlar'];if(!labels.includes(tab))tab='Özet';let iv=records('invoice').filter(x=>x.customer===c.id),os=records('order').filter(x=>x.customer===c.id),ts=records('ticket').filter(x=>x.customer===c.id);let body='';if(tab==='Özet')body=`<div class="stats">${stat('Kayıt tarihi',date(c.created),'','','clock')}${stat('Toplam tahsilat',money(iv.filter(x=>x.status==='Ödendi'&&x.currency==='USD').reduce((n,x)=>n+x.amount,0)),'USD','','wallet')}${stat('Hizmetler',os.length,'Kayıtlı hizmet','','grid')}${stat('Destek talepleri',ts.length,'Toplam talep','','support')}</div><div class="detail-grid">${panel('Müşteri Bilgileri',`<div class="panel-body"><div class="list-row" style="padding:0 0 20px"><span class="avatar">${esc(initials(c.name))}</span><div><b>${esc(c.name)}</b><small>${esc(c.company)}</small></div></div><div class="data-pairs">${[['E-posta',c.email],['Telefon',c.phone],['Konum',c.country],['Durum',c.status],['Para Birimi',c.currency],['Kayıt Tarihi',date(c.created)]].map(([l,v])=>`<div><small>${l}</small>${esc(v||'—')}</div>`).join('')}</div></div>`,'users')}${panel('Muhasebe',`<div class="panel-body"><small class="muted">ÖDENMEMİŞ FATURALAR · USD</small><h2 style="color:var(--red)">${money(iv.filter(x=>x.status==='Ödenmedi'&&x.currency==='USD').reduce((n,x)=>n+x.amount,0))}</h2><div class="progress"><i></i></div><p class="muted tiny">${iv.length} fatura kaydı</p>${btn('+ Yeni Fatura','new','soft',`data-type="invoice" data-customer="${c.id}"`)}</div>`,'wallet')}${panel('İşlemler',`<div class="panel-body stack">${btn('Profili düzenle','edit','',`data-id="${c.id}" data-type="customer"`)}${btn('Yeni hizmet ekle','new','',`data-type="order" data-customer="${c.id}"`)}${btn('Destek talebi oluştur','new','',`data-type="ticket" data-customer="${c.id}"`)}</div>`,'gear')}</div>`;else if(tab==='Profil')body=`<div class="panel-body"><div class="data-pairs">${Object.entries({Ad:c.name,'E-posta':c.email,Telefon:c.phone,Adres:c.address,Firma:c.company,Ülke:c.country}).map(([k,v])=>`<div><small>${k}</small>${esc(v||'—')}</div>`).join('')}</div><div class="form-actions">${btn('Profili Düzenle','edit','primary',`data-id="${c.id}" data-type="customer"`)}</div></div>`;else if(['Faturalar','Cari Ekstre','Ürün & Hizmetler','Destek Talepleri'].includes(tab)){const list=tab==='Ürün & Hizmetler'?os:tab==='Destek Talepleri'?ts:iv;body=list.length?`<table><thead><tr><th>Kayıt</th><th>Tarih</th><th>Durum</th><th>Tutar</th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(x.name)}</td><td>${date(x.created)}</td><td>${tag(x.status)}</td><td>${money(x.amount,x.currency)}</td></tr>`).join('')}</tbody></table>`:empty('Bu müşteri için kayıt yok.')}else if(tab==='Notlar')body=`<div class="panel-body">${esc(c.notes||'Henüz not eklenmedi.')}<div class="form-actions">${btn('Notları düzenle','edit','',`data-id="${c.id}" data-type="customer"`)}</div></div>`;else body=empty('Bu bölüm için kayıt bulunmuyor.','Bu alan diğer panellerden veya harici servislerden otomatik veri almaz.');return heading(c.name)+`<section class="panel">${tabs(labels)}<div class="panel-body">${body}</div></section>`}
function invoiceNew(){return heading()+`<form id="invoice-form"><div class="info">Bu form yönetim paneline fatura kaydı ekler. Resmî e-fatura düzenlemez ve müşteriye otomatik e-posta göndermez.</div><div class="invoice-layout"><div class="stack"><section class="panel"><div class="panel-body">${select('customer','Müşteri',[['','Müşteri seçin'],...records('customer').map(c=>[c.id,c.name])],invoiceNew.customer||'')}<div class="field-pair">${input('issued','Fatura Tarihi',new Date().toISOString().slice(0,10),'date',true)}${input('due','Son Ödeme Tarihi',new Date(Date.now()+7*864e5).toISOString().slice(0,10),'date',true)}</div>${input('name','Fatura Numarası','BM-'+Date.now().toString().slice(-6),'text',true)}</div></section><section class="panel"><header class="panel-head"><h2>Fatura Kalemleri</h2></header><div class="panel-body"><div class="invoice-item tiny muted"><span>Açıklama</span><span>Adet</span><span>Birim Fiyat</span><span></span></div><div id="invoice-lines"></div>${btn('+ Yeni Kalem Ekle','invoice-add','soft','type="button"')}</div></section>${area('notes','Notlar')}</div><aside class="stack"><section class="panel"><div class="panel-body">${select('status','Ödeme Durumu',['Ödenmedi','Ödendi','İptal Edildi'],'Ödenmedi')}<div class="info warning">Bildirim gönderimi bağlı değil.</div>${select('currency','Para Birimi',['USD','BRL','EUR','TRY'],'USD')}${input('discount','İndirim (%)','0','number')}<div class="invoice-total"><b>Ödenecek Tutar</b><strong id="invoice-total">0,00</strong></div>${btn('Fatura Kaydını Oluştur','submit','primary','type="submit" style="width:100%"')}</div></section></aside></div></form>`}
function drawLines(){const el=$('#invoice-lines');if(!el)return;el.innerHTML=invoiceLines.map((x,i)=>`<div class="invoice-item"><input aria-label="Kalem açıklaması" data-line="${i}" data-key="name" value="${esc(x.name)}" required placeholder="Ürün veya hizmet"><input aria-label="Adet" data-line="${i}" data-key="qty" type="number" min="1" max="10000" step="1" value="${x.qty}" required><input aria-label="Birim fiyat" data-line="${i}" data-key="price" type="number" min="0" max="10000000" step="0.01" value="${x.price}" required><button class="icon-btn" type="button" data-action="invoice-remove" data-index="${i}" aria-label="Kalemi kaldır" ${invoiceLines.length===1?'disabled':''}>×</button></div>`).join('');updateTotal()}
function invoiceTotal(){const discount=Math.min(100,Math.max(0,Number($('#invoice-form [name=discount]')?.value||0)));return Math.round(invoiceLines.reduce((n,x)=>n+Number(x.qty)*Number(x.price),0)*(1-discount/100)*100)/100}
function updateTotal(){if($('#invoice-total'))$('#invoice-total').textContent=money(invoiceTotal(),$('#invoice-form [name=currency]').value)}
function analytics(){const iv=records('invoice');return heading()+`<div class="info">Raporlar yalnızca bu yönetim panelindeki kayıtlardan hesaplanır. Para birimleri birbirine dönüştürülmez.</div><div class="stats">${['USD','BRL','EUR','TRY'].map(c=>stat(c+' Tahsilat',money(iv.filter(x=>x.currency===c&&x.status==='Ödendi').reduce((n,x)=>n+x.amount,0),c),'Ödenen faturalar','accent','chart')).join('')}</div><div class="columns">${panel('Son Altı Ay · USD',`<div class="panel-body">${chart(records('order'),iv.filter(x=>x.status==='Ödendi'))}</div>`,'chart')}${panel('Hizmet Dağılımı',records('order').length?records('order').map(x=>`<div class="list-row">${esc(x.name)}<span class="right">${tag(x.status)}</span></div>`).join(''):empty('Sipariş kaydı bulunmuyor.'),'grid')}</div>`}
function auditPage(){return heading()+`<section class="panel"><div class="toolbar">${icon('shield')} Yönetim panelinde gerçekleştirilen kayıt işlemleri ${btn('JSON İndir','backup','small')}</div><div class="table-scroll"><table><thead><tr><th>İşlem</th><th>Kullanıcı</th><th>Tarih</th><th>Kayıt</th></tr></thead><tbody>${state.audit.length?state.audit.map(x=>`<tr><td>${esc(x.action)}</td><td>${esc(x.actor)}</td><td>${new Date(x.created).toLocaleString('tr-TR')}</td><td>${esc(x.target)}</td></tr>`).join(''):`<tr><td colspan="4">${empty('Henüz işlem kaydı yok.')}</td></tr>`}</tbody></table></div></section>`}
function render(){document.querySelectorAll('.nav details').forEach(x=>x.open=false);const pages={overview,general,theme,security,payments,currencies,languages,templates,permissions,customerDetail,invoiceNew,analytics,audit:auditPage,customers:()=>listPage('customer'),invoices:()=>listPage('invoice'),staff:()=>listPage('staff'),orders:()=>listPage('order'),support:()=>listPage('ticket'),products:()=>listPage('product'),notes:()=>listPage('note'),reminders:()=>listPage('reminder'),tasks:()=>listPage('task')};$('#main').innerHTML=(pages[route()]||overview)();icons();if(route()==='invoiceNew')drawLines();document.title=(names[route()]||'Başlangıç')+' · Brazil Migration';}
function edit(type,id='',customer=''){if(demo)return toast('Önizleme salt okunurdur. Gerçek kayıtlara dönün.');let x=state.records.find(x=>x.id===id)||{};if(id.startsWith('template-'))x={name:templateDefaults[Number(id.split('-')[1])],category:'Genel Bildirimler'};let body='';const cs=[['','Müşteri seçin'],...records('customer').map(c=>[c.id,c.name])];if(type==='invoice'&&!id){invoiceNew.customer=customer;invoiceLines=[{name:'',qty:1,price:0}];location.hash='invoiceNew';if(route()==='invoiceNew')render();return}body=input('name',type==='customer'||type==='staff'?'Adı Soyadı':'Başlık',x.name||'','text',true);if(['customer','staff'].includes(type)){body+=`<div class="field-pair">${input('email','E-posta',x.email||'','email',true)}${input('phone','Telefon',x.phone||'','tel')}</div>`;if(type==='customer')body+=`<div class="field-pair">${input('company','Firma',x.company||'')}${select('country','Ülke',['Brezilya','Türkiye','Azerbaycan','Kuzey Makedonya','Rusya','İspanya','İran','Suudi Arabistan','Türkmenistan','Özbekistan','Kırgızistan','Endonezya','Diğer'],x.country||'Türkiye')}</div>${area('address','Adres',x.address||'')}${select('currency','Para Birimi',['USD','BRL','EUR','TRY'],x.currency||'USD')}${area('notes','Notlar',x.notes||'')}`;else body+=`<div class="info warning">Bu işlem personel kaydı oluşturur. Giriş hesabı veya davet oluşturmaz.</div>${input('group','Yetki Grubu',x.group||'Destek Ekibi')}${select('department','Departman',['Genel','Satış','Muhasebe','Hukuk','Teknik Destek'],x.department||'Genel')}`;body+=select('status','Durum',['Aktif','Pasif'],x.status||'Aktif')}else if(type==='template')body+=select('category','Kategori',['Genel Bildirimler','Bülten','Yönetici Bildirimleri','Fatura','Sipariş','Ürün/Hizmet','Destek','Güvenlik'],x.category)+select('channel','Kanal',['E-posta','SMS'],x.channel)+input('subject','Konu',x.subject||'')+area('body','Şablon İçeriği',x.body||'')+select('status','Durum',['Taslak','Hazır'],x.status||'Taslak')+'<p class="tiny muted">Şablon kaydedilir; mesaj gönderilmez.</p>';else if(type==='order'||type==='ticket'){body+=select('customer','Müşteri',cs,x.customer||customer);if(type==='order')body+=input('amount','Tutar',x.amount||0,'number')+select('currency','Para Birimi',['USD','BRL','EUR','TRY'],x.currency||'USD')+select('status','Durum',['İşlemde','Tamamlandı','İptal Edildi'],x.status);else body+=select('department','Departman',['Genel','Muhasebe','Hukuk','Teknik Destek'],x.department)+select('status','Durum',['Yanıt Bekliyor','İşlemde','Kapandı'],x.status);body+=area('description','Açıklama / Notlar',x.description||'')}else if(type==='invoice')body+=select('customer','Müşteri',cs,x.customer)+input('amount','Tutar',x.amount,'number')+select('currency','Para Birimi',['USD','BRL','EUR','TRY'],x.currency)+input('due','Son Ödeme Tarihi',x.due,'date')+select('status','Durum',['Ödenmedi','Ödendi','İptal Edildi'],x.status)+area('notes','Notlar',x.notes||'');else{body+=area('description','Açıklama',x.description||'');if(type==='product')body+=input('amount','Fiyat',x.amount||0,'number')+select('currency','Para Birimi',['USD','BRL','EUR','TRY'],x.currency||'USD');else body+=input('due','Tarih',x.due||'','date');body+=select('status','Durum',type==='product'?['Aktif','Pasif']:['Açık','Tamamlandı'],x.status)}modal((id?'Düzenle: ':'Yeni ')+(typeTitles[type]||'Kayıt'),`<form data-record="${type}" data-id="${x.id||''}">${body}<div class="form-actions">${x.id?btn('Sil','delete','danger',`type="button" data-id="${x.id}"`):''}${btn('Kaydet','submit','primary','type="submit"')}</div></form>`)}
function viewInvoice(id){const x=records('invoice').find(x=>x.id===id);if(!x)return;let lines=[];try{lines=JSON.parse(x.lines||'[]')}catch{}modal('Fatura '+x.name,`<div id="invoice-preview"><img src="/brazil-migration-logo.png" alt="Brazil Migration" style="width:180px"><div class="statusbar"><span>Yönetim fatura kaydı · Resmî belge değildir</span>${tag(x.status)}</div><h3>${esc(customerName(x.customer))}</h3><p class="muted">${esc(x.name)} · Son ödeme: ${date(x.due)}</p>${lines.length?`<table><thead><tr><th>Açıklama</th><th>Adet</th><th>Tutar</th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.qty)}</td><td>${money(l.price*l.qty,x.currency)}</td></tr>`).join('')}</tbody></table>`:''}<div class="invoice-total"><b>Toplam</b><strong>${money(x.amount,x.currency)}</strong></div><p>${esc(x.notes||'')}</p></div><div class="form-actions">${btn('Kaydı İndir','invoice-download','',`data-id="${x.id}"`)}${btn('Düzenle','edit','primary',`data-type="invoice" data-id="${x.id}"`)}</div>`)}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function search(){modal('Akıllı Arama',`<input id="global-search" placeholder="Sayfa, müşteri, fatura veya kayıt ara…" aria-label="Akıllı arama"><div id="search-results"></div>`);globalSearch('');$('#global-search').focus()}
function globalSearch(q){const entries=[...Object.entries(names).filter(([k])=>!['invoiceNew','customerDetail'].includes(k)).map(([key,name])=>({name,url:'#'+key})),...state.records.map(x=>({name:x.name,url:x.type==='customer'?'#customerDetail/'+x.id:'#'+({invoice:'invoices',order:'orders',ticket:'support',staff:'staff',template:'templates',product:'products',task:'tasks',note:'notes',reminder:'reminders'}[x.type]||'overview')}))];$('#search-results').innerHTML=entries.filter(x=>x.name?.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))).slice(0,12).map(x=>`<a class="search-result" href="${esc(x.url)}" data-action="close">${icon('search')} ${esc(x.name)} →</a>`).join('')||empty('Sonuç bulunamadı.')}
function refreshTable(){const el=$('.table-shell');if(el){const focused=document.activeElement?.id==='table-search',pos=$('#table-search')?.selectionStart;el.outerHTML=renderTable(currentType);if(focused){$('#table-search').focus();$('#table-search').setSelectionRange(pos,pos)}}}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-tab],[data-side],[data-language]');if(!t)return;if(t.dataset.tab){tab=t.dataset.tab;side='';render();return}if(t.dataset.side){side=t.dataset.side;render();return}if(t.dataset.language){t.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===t));toast(t.dataset.language+' görünümü seçildi. Dil çevirileri uygulanmaz.');return}const a=t.dataset.action;try{if(a==='submit')return;if(a==='close')close();else if(a==='search')search();else if(a==='demo'){demo=!demo;render()}else if(a==='profile')modal('Yönetici Profili',`<div class="list-row"><span class="avatar">${esc(initials(state.member.name))}</span><div><b>${esc(state.member.name)}</b><small>${esc(state.member.email)}</small></div></div><div class="info">Bu alan mevcut site sahibi kimliğiyle açılır. Ek bir panel şifresi istenmez.</div><a class="btn" href="#general" data-action="close">Genel ayarlar →</a>`);else if(a==='help')modal('Yönetim Paneli Hakkında','<p>PDF’deki ekran yapısı Brazil Migration renkleriyle hazırlanmıştır.</p><p>Müşteri, fatura, personel, sipariş, görev ve not kayıtları bu yönetim alanında kalıcı olarak saklanır. Diğer panellere aktarılmaz.</p><p>Ayarlar taslak olarak kaydedilir. Ödeme, e-posta, SMS, canlı oturum takibi ve harici doğrulama bağlantıları henüz kurulmadı.</p><p class="muted">Ctrl / ⌘ + K ile akıllı aramayı açabilirsiniz.</p>');else if(a==='notifications')modal('Bildirim Merkezi',state.audit.length?state.audit.slice(0,8).map(x=>`<div class="list-row">${icon('bell')}<div>${esc(x.action)}<small>${new Date(x.created).toLocaleString('tr-TR')}</small></div></div>`).join(''):empty('Henüz bildirim bulunmuyor.'));else if(a==='shortcuts')modal('Hızlı Erişim',`<div class="module-grid">${[['customers','Müşteriler'],['invoices','Faturalar'],['staff','Personel'],['general','Genel Ayarlar']].map(([r,n])=>`<a href="#${r}" class="btn" data-action="close">${n} →</a>`).join('')}</div>`);else if(a==='new'||a==='edit')edit(t.dataset.type,t.dataset.id||'',t.dataset.customer||'');else if(a==='prev'||a==='next'){page+=a==='next'?1:-1;refreshTable()}else if(a==='invoice-view')viewInvoice(t.dataset.id);else if(a==='invoice-add'){invoiceLines.push({name:'',qty:1,price:0});drawLines()}else if(a==='invoice-remove'){invoiceLines.splice(Number(t.dataset.index),1);drawLines()}else if(a==='invoice-download'){const x=records('invoice').find(x=>x.id===t.dataset.id);download('fatura-'+x.name.replace(/[^a-z0-9-]/gi,'')+'.html',`<!doctype html><html lang="tr"><meta charset="utf-8"><title>${esc(x.name)}</title><style>body{font:14px Arial;padding:40px;color:#184d32}table{border-collapse:collapse;width:100%}td,th{padding:14px;border-bottom:1px solid #ddd;text-align:left}.invoice-total{font-size:24px;margin-top:25px}img{max-width:180px}</style>${$('#invoice-preview').innerHTML.replace(/<img[^>]+>/,'<h1>Brazil Migration</h1>')}</html>`,'text/html')}else if(a==='delete'){modal('Kaydı Sil',`<p>Bu kayıt kalıcı olarak silinecek.</p><div class="form-actions">${btn('Vazgeç','close')}${btn('Kaydı Sil','delete-confirm','danger',`data-id="${t.dataset.id}"`)}</div>`)}else if(a==='delete-confirm'){await api('record',{id:t.dataset.id},'DELETE');close();await reload();render();toast('Kayıt silindi.')}else if(a==='backup')download('brazil-migration-admin.json',JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2));else if(a==='export'){const headers=[...new Set(currentRows.flatMap(x=>Object.keys(x)))];const cell=x=>{let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('brazil-migration-'+currentType+'.csv','\uFEFF'+[headers.map(cell).join(';'),...currentRows.map(x=>headers.map(k=>cell(x[k])).join(';'))].join('\r\n'),'text/csv;charset=utf-8')}else if(a==='provider')modal(t.dataset.name+' Yapılandırma Notu',`<form data-config="provider-${t.dataset.name.toLowerCase().replaceAll(' ','-')}"><div class="info warning">Bu kayıt sağlayıcıyı bağlamaz. Gizli anahtar veya parola girmeyin.</div>${area('notes','Entegrasyon Notları',state.config['provider-'+t.dataset.name.toLowerCase().replaceAll(' ','-')]?.notes||'')}<div class="form-actions">${btn('Notu Kaydet','submit','primary','type="submit"')}</div></form>`);else if(a==='image')modal(t.dataset.title,`<img src="${esc(t.dataset.src)}" alt="${esc(t.dataset.title)}" style="width:100%">`)}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){tableQuery=e.target.value;page=1;refreshTable()}if(e.target.id==='global-search')globalSearch(e.target.value);if(e.target.matches('[data-filter-static]'))document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase('tr').includes(e.target.value.toLocaleLowerCase('tr')));if(e.target.dataset.line!==undefined){const x=invoiceLines[Number(e.target.dataset.line)];x[e.target.dataset.key]=e.target.dataset.key==='name'?e.target.value:Number(e.target.value);updateTotal()}if(e.target.closest('#invoice-form'))updateTotal();if(route()==='general'&&tab==='SEO'){if(e.target.name==='title')$('#seo-preview-title').textContent=e.target.value;if(e.target.name==='description')$('#seo-preview-description').textContent=e.target.value}});
document.addEventListener('change',e=>{if(e.target.id==='table-status'){tableStatus=e.target.value;page=1;refreshTable()}if(e.target.hasAttribute('data-all-permissions'))document.querySelectorAll('[data-permission]').forEach(x=>x.checked=e.target.checked)});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-config],[data-record],#invoice-form'))return;e.preventDefault();if(demo)return toast('Önizlemede kayıt yapılamaz. Gerçek kayıtlara dönün.');const button=e.submitter;if(button)button.disabled=true;try{const values=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox]').forEach(x=>values[x.name]=x.checked);if(form.dataset.config){const section=form.dataset.config;await api('config',{section,values:{...state.config[section],...values}});toast('Ayar taslağı kaydedildi.')}else{let body={...values,type:form.dataset.record,id:form.dataset.id||undefined};if(form.id==='invoice-form'){if(!values.customer)throw new Error('Müşteri seçin.');if(invoiceLines.some(x=>!x.name.trim()||x.qty<=0||x.price<0))throw new Error('Fatura kalemlerini kontrol edin.');body={...values,type:'invoice',amount:invoiceTotal(),lines:JSON.stringify(invoiceLines),discount:Number(values.discount||0)}}else if('amount'in body)body.amount=Number(body.amount);await api('record',body);toast('Kayıt kaydedildi.')}close();await reload();if(form.id==='invoice-form')location.hash='invoices';else render()}catch(err){toast(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav'))document.querySelectorAll('.nav details').forEach(x=>x.open=false)});
window.addEventListener('hashchange',()=>{tab='';side='';tableQuery='';tableStatus='';page=1;render();window.scrollTo(0,0)});
icons();reload().then(render).catch(e=>{$('#main').innerHTML=`<div class="panel"><div class="empty">${icon('shield')}<h1 style="font-size:20px">Yönetici erişimi</h1><p>${esc(e.message)}</p><a class="btn primary" href="/admin/giris/">Site sahibi olarak giriş yap</a><a href="/">Web sitesine dön</a></div></div>`});
